queries.sql:
SELECT ledger_payments.pay_date, ledger_payments.pay_amount AS bank_exp
FROM ledger_payments
WHERE (((ledger_payments.pay_mode)=2));

SELECT ledger_receipt.pay_date, ledger_receipt.pay_mode, ledger_receipt.amount
FROM ledger_receipt
WHERE (((ledger_receipt.pay_mode)=2));

SELECT sales_exp_rb.pay_date, sales_exp_rb.amount, sales_exp_rb.expenses, (Select Sum(nz([amount],0)-nz([expenses],0))From date_sale_exp_query Where date_sale_exp_query.pay_date<=sales_exp_rb.pay_date) AS balance
FROM date_sale_exp_query AS sales_exp_rb
ORDER BY sales_exp_rb.pay_date;

SELECT ledger_receipt.pay_date, ledger_receipt.pay_mode, ledger_receipt.amount
FROM ledger_receipt
WHERE (((ledger_receipt.pay_mode)=1));

SELECT item_category.cat_id, item_category.category
FROM item_category
UNION SELECT 0,"All Category" from item_category;

SELECT item_category.cat_id, item_category.category, Sum(items_list_query.st_value) AS closing
FROM item_category LEFT JOIN items_list_query ON item_category.category = items_list_query.category
GROUP BY item_category.cat_id, item_category.category;

SELECT contra_entry.deposit_date, Sum(contra_entry.amount) AS contra_amount
FROM contra_entry
GROUP BY contra_entry.deposit_date;

SELECT ledgergroup.lggID, ledger.ledgername, ledger.opening_balance
FROM ledgergroup INNER JOIN ledger ON ledgergroup.lggID = ledger.ledgergroup
WHERE (((ledgergroup.lggID)=2));

SELECT ledger.lgID, ledger.ledgername, ledger_payments.pay_amount, ledger_payments.pay_date, ledgergroup.lggID
FROM (ledgergroup INNER JOIN ledger ON ledgergroup.lggID = ledger.ledgergroup) INNER JOIN ledger_payments ON (ledger.lgID = ledger_payments.ledger_id) AND (ledger.lgID = ledger_payments.ledger_id)
WHERE (((ledgergroup.lggID)=2));

SELECT ledger.lgID, ledger.ledgername, ledger.contactnumber, ledgers_sales_query.credit, ledgers_payment_query.debit, Nz([credit],0)-Nz([debit],0) AS balance, [ledger]![ledgername] & [contactnumber] AS search
FROM (ledgers_sales_query LEFT JOIN ledger ON ledgers_sales_query.lgID = ledger.lgID) LEFT JOIN ledgers_payment_query ON ledger.lgID = ledgers_payment_query.lgID
WHERE (((ledger.ledgergroup)=(2) Or (ledger.ledgergroup)=(3) Or (ledger.ledgergroup)=(4)));

SELECT sales_entry.SEID, sales_entry.sales_date, ledger.ledgername, sales_entry.customer_id, ledger.GSTNo, sales_entry.sale_type, sales_entry.final_bill, sales_entry.total_bill, sales_entry.total_tax, sales_entry.labour, sales_entry.discount, sales_entry.total_qty, sales_entry.total_bill_sft, sales_entry.item_category, sales_entry.customer_id AS search
FROM ledger INNER JOIN sales_entry ON ledger.lgID = sales_entry.customer_id
ORDER BY sales_entry.SEID, sales_entry.sales_date;

SELECT ledger_payments.ledger_id, ledger_payments.pay_amount, ledgergroup.lggID, ledger_payments.pay_date
FROM (ledgergroup INNER JOIN ledger ON ledgergroup.lggID = ledger.ledgergroup) INNER JOIN ledger_payments ON (ledger.lgID = ledger_payments.ledger_id) AND (ledger.lgID = ledger_payments.ledger_id)
WHERE (((ledgergroup.lggID)=7));

SELECT ledger_payments.pay_ID, ledger.lgID, ledger.ledgername, ledger_payments.pay_date, ledger_payments.pay_mode, ledger_payments.pay_amount, ledger_payments.remarks
FROM ledger INNER JOIN ledger_payments ON (ledger.lgID = ledger_payments.ledger_id) AND (ledger.lgID = ledger_payments.ledger_id)
ORDER BY ledger_payments.pay_ID, ledger_payments.pay_date;

SELECT ledger.lgID, ledger.ledgername, ledger.ledgergroup, ledger_receipt.pay_date, ledger_receipt.amount
FROM ledger LEFT JOIN ledger_receipt ON ledger.lgID = ledger_receipt.ldger_id
WHERE (((ledger.ledgergroup)=11));

SELECT ledger_payments.ledger_id, ledger_payments.pay_amount AS total_exp, ledgergroup.lggID, ledger_payments.pay_date
FROM (ledgergroup INNER JOIN ledger ON ledgergroup.lggID = ledger.ledgergroup) INNER JOIN ledger_payments ON (ledger.lgID = ledger_payments.ledger_id) AND (ledger.lgID = ledger_payments.ledger_id)
WHERE (((ledgergroup.lggID)=6));

SELECT items.item_id, items.item_name, items.item_sft, materials.mat_tax, materials.mat_pur_price, materials.material_name, items.itemcode, items.unit, materials.mat_sale_price, item_category.category, items.discontinue, materials.mat_id, item_bal_query.balance_qty, Nz([balance_qty],0)*Nz([items]![item_sft],0) AS st_sft, items.material, Nz([st_sft],0)*Nz([materials]![mat_pur_price],0) AS st_value
FROM units INNER JOIN (item_category INNER JOIN (materials INNER JOIN (items LEFT JOIN item_bal_query ON items.item_id = item_bal_query.item_id) ON (materials.mat_id = items.material) AND (materials.mat_id = items.material)) ON item_category.cat_id = materials.category_id) ON units.unit_ID = materials.unit
ORDER BY items.item_name;

SELECT sales_entry.sales_date, Sum(sales_entry.labour) AS labour, Sum(sales_entry.discount) AS discount, Sum(sales_entry.total_tax) AS tax
FROM sales_entry
GROUP BY sales_entry.sales_date;

SELECT ledger.lgID, ledger.ledgername, ledger.ledgergroup, ledgers_sales_query.credit, ledgers_payment_query.debit, Nz([credit],0)-Nz([debit],0) AS balance
FROM (ledgers_sales_query RIGHT JOIN ledger ON ledgers_sales_query.lgID = ledger.lgID) LEFT JOIN ledgers_payment_query ON ledger.lgID = ledgers_payment_query.lgID
WHERE (((ledger.ledgergroup)=3));

SELECT ledger.lgID, ledger_receipt.ldger_id, ledger.ledgername, Sum(ledger_receipt.amount) AS debit
FROM ledger LEFT JOIN ledger_receipt ON ledger.lgID = ledger_receipt.ldger_id
GROUP BY ledger.lgID, ledger_receipt.ldger_id, ledger.ledgername;

SELECT sales_entry.sales_date, sales_entry.customer_id, Sum(sales_entry.final_bill) AS final_bill
FROM sales_entry
GROUP BY sales_entry.sales_date, sales_entry.customer_id;

SELECT ledger.lgID, ledger.ledgername, Sum(ledger_receipt.amount) AS debit
FROM ledger LEFT JOIN ledger_receipt ON ledger.lgID = ledger_receipt.ldger_id
GROUP BY ledger.lgID, ledger.ledgername;

SELECT purchase_entry.pur_date, ledger.lgID, ledger.ledgername, Sum(purchase_entry.final_total) AS credit
FROM ledger INNER JOIN purchase_entry ON ledger.lgID = purchase_entry.sup_id
GROUP BY purchase_entry.pur_date, ledger.lgID, ledger.ledgername;

SELECT ledger.lgID, ledger.ledgername, Sum(sales_entry.final_bill) AS credit
FROM ledger INNER JOIN sales_entry ON ledger.lgID = sales_entry.customer_id
GROUP BY ledger.lgID, ledger.ledgername;

SELECT purchase_detail.item_id, Sum(purchase_detail.qty) AS pur_qty
FROM purchase_entry INNER JOIN purchase_detail ON purchase_entry.PEID = purchase_detail.PEID
GROUP BY purchase_detail.item_id;

SELECT sales_entry.sales_date, items.item_id, items.item_name, sales_detail.qty, sales_detail.total_sft, materials.mat_id
FROM sales_entry INNER JOIN ((materials INNER JOIN items ON (materials.mat_id = items.material) AND (materials.mat_id = items.material)) INNER JOIN sales_detail ON items.item_id = sales_detail.item_id) ON sales_entry.SEID = sales_detail.SEID
ORDER BY sales_entry.sales_date;

SELECT purchase_detail.item_id, Sum(purchase_detail.qty) AS purqty
FROM purchase_detail
GROUP BY purchase_detail.item_id;

SELECT sales_detail.item_id, Sum(sales_detail.qty) AS saleqty
FROM sales_detail
GROUP BY sales_detail.item_id;

SELECT sales_entry.SEID, sales_entry.sales_date, sales_entry.customer_id, sales_entry.tax_type, sales_entry.sale_type, sales_entry.final_bill, sales_entry.total_bill, sales_entry.total_tax, sales_entry.labour, sales_entry.discount, sales_entry.total_qty, sales_entry.total_bill_sft, item_category.category, [SEID] & [ledgername] & [sale_type]![sale_type] & [category] AS Search
FROM item_category INNER JOIN (sale_type INNER JOIN (sale_tax_type INNER JOIN (ledger INNER JOIN sales_entry ON ledger.lgID = sales_entry.customer_id) ON sale_tax_type.sale_txtype_ID = sales_entry.tax_type) ON sale_type.saletype_ID = sales_entry.sale_type) ON item_category.cat_id = sales_entry.item_category
ORDER BY sales_entry.SEID, sales_entry.final_bill;

SELECT sales_detail.item_id, Sum(sales_detail.qty) AS sales_qty
FROM sales_detail
GROUP BY sales_detail.item_id;

SELECT sales_entry.SEID, sales_entry.customer_id, ledger.GSTNo, sales_entry.sales_date, sales_entry.tax_type, sales_entry.final_bill, sales_entry.total_bill, sales_entry.outputsgst, sales_entry.outputcgst, sales_entry.outputigst, sales_entry.labour, sales_entry.discount, sales_entry.total_bill_sft, sales_entry.item_category
FROM sale_tax_type INNER JOIN (ledger INNER JOIN (item_category RIGHT JOIN sales_entry ON item_category.cat_id = sales_entry.item_category) ON ledger.lgID = sales_entry.customer_id) ON sale_tax_type.sale_txtype_ID = sales_entry.tax_type
ORDER BY sales_entry.SEID, sales_entry.sales_date;

SELECT stock_in.item_id, stock_in.item_name, Sum(stock_in.st_in_qty) AS st_in_qty
FROM stock_in
GROUP BY stock_in.item_id, stock_in.item_name;

SELECT stock_out.item_id, stock_out.item_name, Sum(stock_out.st_out_qty) AS st_out_qty
FROM stock_out
GROUP BY stock_out.item_id, stock_out.item_name;

SELECT ledger.lgID, ledger.ledgername, ledger.ledgergroup, ledgers_purchase_query.credit, ledgers_payment_query.debit, Nz([debit],0)-Nz([credit],0) AS balance
FROM (ledger LEFT JOIN ledgers_purchase_query ON ledger.lgID = ledgers_purchase_query.lgID) LEFT JOIN ledgers_payment_query ON ledger.lgID = ledgers_payment_query.lgID
WHERE (((ledger.ledgergroup)=2));

SELECT Count(ledger_payments.pay_ID) AS CountOfpay_ID, ledger_payments.pay_date, Sum(ledger_payments.pay_amount) AS expenses
FROM ledger_payments
GROUP BY ledger_payments.pay_date;

SELECT Count(purchase_entry.PEID) AS CountOfPEID, purchase_entry.pur_date, Sum(purchase_entry.final_total) AS purchase
FROM purchase_entry
GROUP BY purchase_entry.pur_date;

SELECT Count(ledger_receipt.ID) AS CountOfID, ledger_receipt.pay_date, Sum(ledger_receipt.amount) AS amount
FROM ledger_receipt
GROUP BY ledger_receipt.pay_date;

SELECT Count(sales_entry.SEID) AS CountOfSEID, sales_entry.sales_date, Sum(sales_entry.final_bill) AS sales_amount
FROM sales_entry
GROUP BY sales_entry.sales_date;
